from typing import List


def total_answers(query_type: List[str], student1: List[int], student2: List[int]) -> List[int]:
    parent: dict = {}
    size: dict = {}

    def find(x: int) -> int:
        if x not in parent:                 # students we haven't seen are singleton groups
            parent[x], size[x] = x, 1
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:            # path compression
            parent[x], x = root, parent[x]
        return root

    res = []
    for q, a, b in zip(query_type, student1, student2):
        ra, rb = find(a), find(b)
        if q == "Friend":
            if ra != rb:
                if size[ra] < size[rb]:
                    ra, rb = rb, ra
                parent[rb] = ra             # union by size
                size[ra] += size[rb]
        else:                               # Total
            res.append(size[ra] if ra == rb else size[ra] + size[rb])
    return res


def find_circle_num(query_type: List[str], student1: List[int], student2: List[int]) -> int:
    # the signature returns one int: the answer of the (last) Total query
    res = total_answers(query_type, student1, student2)
    return res[-1] if res else 0


if __name__ == "__main__":
    assert find_circle_num(["Friend", "Friend", "Total"], [1, 2, 1], [2, 3, 4]) == 4
    assert total_answers(["Total", "Friend", "Total", "Total"], [1, 1, 1, 2], [2, 2, 2, 5]) == [2, 2, 3]
